package locksvc

import (
	"errors"
	"testing"
	"time"
)

func newService(t *testing.T) (*Service, *time.Time) {
	t.Helper()
	base := time.Date(2026, 1, 1, 12, 0, 0, 0, time.UTC)
	now := base
	svc := New(WithClock(func() time.Time { return now }))
	t.Cleanup(func() {})
	return svc, &now
}

func advance(now *time.Time, d time.Duration) { *now = now.Add(d) }

func TestAcquireFreeResource(t *testing.T) {
	svc, now := newService(t)

	outcome, err := svc.Acquire("Doc-1", " Node-A ", 30)
	if err != nil {
		t.Fatalf("acquire: %v", err)
	}
	if outcome.Status != StatusAcquired {
		t.Fatalf("status = %q", outcome.Status)
	}
	st := outcome.State
	if !st.Exists || !st.Locked {
		t.Fatalf("exists/locked = %v/%v", st.Exists, st.Locked)
	}
	if st.OwnerID != " Node-A " || st.ResourceID != "Doc-1" {
		t.Fatalf("identities were rewritten: %+v", st)
	}
	if st.ReentryCount != 1 {
		t.Fatalf("reentry = %d", st.ReentryCount)
	}
	want := now.Add(30 * time.Second)
	if !st.LeaseExpiresAt.Equal(want) {
		t.Fatalf("expiry = %v, want %v", st.LeaseExpiresAt, want)
	}
	if len(st.Waiting) != 0 {
		t.Fatalf("waiting = %+v", st.Waiting)
	}
}

func TestReentryKeepsOriginalExpiry(t *testing.T) {
	svc, now := newService(t)

	first, _ := svc.Acquire("r", "a", 30)
	advance(now, 5*time.Second)
	outcome, err := svc.Acquire("r", "a", 99)
	if err != nil {
		t.Fatalf("reentry: %v", err)
	}
	if outcome.Status != StatusReentry || outcome.State.ReentryCount != 2 {
		t.Fatalf("outcome = %+v", outcome)
	}
	if !outcome.State.LeaseExpiresAt.Equal(first.State.LeaseExpiresAt) {
		t.Fatalf("lease changed by reentry")
	}

	explicit, err := svc.Reenter("r", "a")
	if err != nil || explicit.State.ReentryCount != 3 {
		t.Fatalf("explicit reentry = %+v, %v", explicit, err)
	}
	if !explicit.State.LeaseExpiresAt.Equal(first.State.LeaseExpiresAt) {
		t.Fatalf("explicit reentry changed lease")
	}
}

func TestWaitersEnqueueInOrderAndRejectDuplicates(t *testing.T) {
	svc, _ := newService(t)
	svc.Acquire("r", "a", 30)

	b, err := svc.Acquire("r", "b", 20)
	if err != nil || b.Status != StatusWaiting {
		t.Fatalf("b = %+v, %v", b, err)
	}
	svc.Acquire("r", "c", 40)

	if _, err := svc.Acquire("r", "b", 20); !errors.Is(err, ErrDuplicateWaiter) {
		t.Fatalf("duplicate waiter = %v", err)
	}
	if _, err := svc.Acquire("r", "b", 20); !errors.Is(err, DuplicateWaiterError) {
		t.Fatalf("named error alias failed: %v", err)
	}

	st, _ := svc.GetResource("r")
	if len(st.Waiting) != 2 || st.Waiting[0].OwnerID != "b" || st.Waiting[1].OwnerID != "c" {
		t.Fatalf("waiting order = %+v", st.Waiting)
	}
	if st.Waiting[1].RequestedLeaseSeconds != 40 {
		t.Fatalf("lease seconds lost: %+v", st.Waiting[1])
	}
}

func TestDuplicateHoldAcrossResources(t *testing.T) {
	svc, _ := newService(t)
	if _, err := svc.Acquire("r1", "a", 30); err != nil {
		t.Fatal(err)
	}
	// r2 is free, but a already has an active holding elsewhere.
	if _, err := svc.Acquire("r2", "a", 30); !errors.Is(err, ErrDuplicateHold) {
		t.Fatalf("cross-resource acquire = %v, want ErrDuplicateHold", err)
	}

	st, _ := svc.GetResource("r2")
	if st.Exists {
		t.Fatalf("r2 must not be created on duplicate hold: %+v", st)
	}
	holder, _ := svc.GetHolder("a")
	if len(holder.Holds) != 1 || holder.Holds[0].ResourceID != "r1" {
		t.Fatalf("holder = %+v", holder)
	}
	if holder.Holds[0].LeaseSeconds != 30 {
		t.Fatalf("lease seconds = %d", holder.Holds[0].LeaseSeconds)
	}
}

func TestReleaseDecrementsThenTransfers(t *testing.T) {
	svc, now := newService(t)
	svc.Acquire("r", "a", 30)
	svc.Acquire("r", "a", 30)
	svc.Acquire("r", "b", 15)

	dec, err := svc.Release("r", "a")
	if err != nil || dec.Status != StatusReentryDecrement || dec.State.ReentryCount != 1 {
		t.Fatalf("decrement = %+v, %v", dec, err)
	}

	released, err := svc.Release("r", "a")
	if err != nil {
		t.Fatalf("release: %v", err)
	}
	if released.Status != StatusReleased || released.State.OwnerID != "b" {
		t.Fatalf("release = %+v", released)
	}
	want := now.Add(15 * time.Second)
	if !released.State.LeaseExpiresAt.Equal(want) {
		t.Fatalf("new lease = %v, want %v", released.State.LeaseExpiresAt, want)
	}
	if len(released.State.Waiting) != 0 {
		t.Fatalf("queue not drained: %+v", released.State.Waiting)
	}
}

func TestReleaseWithEmptyQueueRemovesResource(t *testing.T) {
	svc, _ := newService(t)
	svc.Acquire("r", "a", 30)
	released, err := svc.Release("r", "a")
	if err != nil || released.State.Exists {
		t.Fatalf("release = %+v, %v", released, err)
	}

	st, _ := svc.GetResource("r")
	if st.Exists || st.Locked {
		t.Fatalf("resource should be gone: %+v", st)
	}
	holder, _ := svc.GetHolder("a")
	if len(holder.Holds) != 0 {
		t.Fatalf("holder still holds: %+v", holder)
	}
}

func TestNonOwnerReleaseAndExpiredOwnerReentry(t *testing.T) {
	svc, now := newService(t)
	svc.Acquire("r", "a", 10)
	svc.Acquire("r", "b", 20)

	if _, err := svc.Release("r", "b"); !errors.Is(err, ErrNotLockOwner) {
		t.Fatalf("waiter release = %v", err)
	}
	if _, err := svc.Release("missing", "a"); !errors.Is(err, ErrNotLockOwner) {
		t.Fatalf("missing resource release = %v", err)
	}

	advance(now, 10*time.Second)
	if _, err := svc.Acquire("r", "a", 10); !errors.Is(err, ErrLeaseExpired) {
		t.Fatalf("expired reentry via acquire = %v", err)
	}
	if _, err := svc.Reenter("r", "a"); !errors.Is(err, ErrLeaseExpired) {
		t.Fatalf("expired reenter = %v", err)
	}
	if _, err := svc.Release("r", "a"); !errors.Is(err, ErrLeaseExpired) {
		t.Fatalf("expired release = %v", err)
	}
	st, _ := svc.GetResource("r")
	if st.OwnerID != "b" {
		t.Fatalf("late action changed holder: %+v", st)
	}
}

func TestExpiryPromotesHeadWaiterWithFreshLease(t *testing.T) {
	svc, now := newService(t)
	svc.Acquire("r", "a", 10)
	svc.Acquire("r", "b", 20)
	svc.Acquire("r", "c", 30)

	advance(now, 10*time.Second)
	st, err := svc.GetResource("r")
	if err != nil {
		t.Fatal(err)
	}
	if !st.Locked || st.OwnerID != "b" || st.ReentryCount != 1 {
		t.Fatalf("after expiry = %+v", st)
	}
	want := now.Add(20 * time.Second)
	if !st.LeaseExpiresAt.Equal(want) {
		t.Fatalf("lease = %v want %v", st.LeaseExpiresAt, want)
	}
	if len(st.Waiting) != 1 || st.Waiting[0].OwnerID != "c" {
		t.Fatalf("queue = %+v", st.Waiting)
	}
}

func TestExpiryWithoutWaitersLeavesFreeResource(t *testing.T) {
	svc, now := newService(t)
	svc.Acquire("r", "a", 10)
	advance(now, 11*time.Second)

	st, _ := svc.GetResource("r")
	if !st.Exists || st.Locked || st.OwnerID != "" || st.ReentryCount != 0 {
		t.Fatalf("expired state = %+v", st)
	}
	holder, _ := svc.GetHolder("a")
	if len(holder.Holds) != 0 {
		t.Fatalf("expired hold reported: %+v", holder)
	}
}

func TestRenewExtendsFromRenewalInstant(t *testing.T) {
	svc, now := newService(t)
	first, _ := svc.Acquire("r", "a", 10)
	advance(now, 8*time.Second)

	outcome, err := svc.Renew("r", "a", 20)
	if err != nil {
		t.Fatalf("renew: %v", err)
	}
	if outcome.Status != StatusRenewed {
		t.Fatalf("status = %q", outcome.Status)
	}
	want := now.Add(20 * time.Second)
	if !outcome.State.LeaseExpiresAt.Equal(want) {
		t.Fatalf("renewed lease = %v want %v", outcome.State.LeaseExpiresAt, want)
	}
	if !outcome.State.LeaseExpiresAt.After(first.State.LeaseExpiresAt) {
		t.Fatalf("renewal did not extend past original expiry")
	}
}

func TestRenewValidation(t *testing.T) {
	svc, now := newService(t)
	svc.Acquire("r", "a", 10)
	if _, err := svc.Renew("r", "a", 0); !errors.Is(err, ErrInvalidLeaseDuration) {
		t.Fatalf("bad duration = %v", err)
	}
	if _, err := svc.Renew("r", "b", 10); !errors.Is(err, ErrNotLockOwner) {
		t.Fatalf("non-owner renew = %v", err)
	}

	advance(now, 10*time.Second)
	if _, err := svc.Renew("r", "a", 10); !errors.Is(err, ErrLeaseExpired) {
		t.Fatalf("expired renew = %v", err)
	}
}

func TestValidationErrors(t *testing.T) {
	svc, _ := newService(t)

	if _, err := svc.Acquire("r", "a", 0); !errors.Is(err, ErrInvalidLeaseDuration) {
		t.Fatalf("zero lease = %v", err)
	}
	if _, err := svc.Acquire("r", "a", -1); !errors.Is(err, InvalidLeaseDurationError) {
		t.Fatalf("negative lease = %v", err)
	}
	if _, err := svc.Acquire("", "a", 1); !errors.Is(err, ErrInvalidLockIdentity) {
		t.Fatalf("empty resource = %v", err)
	}
	if _, err := svc.Acquire("r", "", 1); !errors.Is(err, ErrInvalidHolderIdentity) {
		t.Fatalf("empty owner = %v", err)
	}
	if _, err := svc.AcquireWithReentry("r", "a", 10, -2); !errors.Is(err, ErrInvalidReentryCount) {
		t.Fatalf("negative reentry = %v", err)
	}
	if _, err := svc.Release("", "a"); !errors.Is(err, ErrInvalidLockIdentity) {
		t.Fatalf("release empty resource = %v", err)
	}
	if _, err := svc.Release("r", ""); !errors.Is(err, ErrInvalidHolderIdentity) {
		t.Fatalf("release empty owner = %v", err)
	}
	if _, err := svc.GetResource(""); !errors.Is(err, ErrInvalidLockIdentity) {
		t.Fatalf("query empty resource = %v", err)
	}
	if _, err := svc.GetHolder(""); !errors.Is(err, ErrInvalidHolderIdentity) {
		t.Fatalf("query empty owner = %v", err)
	}
}

func TestQueryUnknownReturnsEmpty(t *testing.T) {
	svc, _ := newService(t)

	st, err := svc.GetResource("never")
	if err != nil || st.Exists || st.Locked || st.OwnerID != "" || st.ReentryCount != 0 || len(st.Waiting) != 0 {
		t.Fatalf("unknown resource = %+v, %v", st, err)
	}
	holder, err := svc.GetHolder("never")
	if err != nil || holder.OwnerID != "never" || len(holder.Holds) != 0 {
		t.Fatalf("unknown holder = %+v, %v", holder, err)
	}
}

func TestAcquireWithInitialReentry(t *testing.T) {
	svc, _ := newService(t)
	outcome, err := svc.AcquireWithReentry("r", "a", 10, 3)
	if err != nil {
		t.Fatal(err)
	}
	if outcome.State.ReentryCount != 3 {
		t.Fatalf("count = %d want 3", outcome.State.ReentryCount)
	}
	dec, _ := svc.Release("r", "a")
	if dec.State.ReentryCount != 2 {
		t.Fatalf("decrement = %d", dec.State.ReentryCount)
	}
}

func TestExpiredOwnerCanQueueWhenWaitersExist(t *testing.T) {
	svc, now := newService(t)
	svc.Acquire("r", "a", 10)
	svc.Acquire("r", "b", 20)
